require_once __DIR__ . '/../includes/auth.php';$u=require_role(['superadmin']);$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT * FROM accounts WHERE id=?");$s->execute([$id]);$a=$s->fetch();if(!$a)exit('Account not found.');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$role=$_POST['role'];$status=$_POST['account_status'];if(!in_array($role,['user','admin','superadmin'],true)||!in_array($status,['active','inactive','suspended'],true))$error='Invalid selection.';else{$activeSup=(int)$pdo->query("SELECT COUNT(*) FROM accounts WHERE role='superadmin' AND account_status='active'")->fetchColumn();if($a['role']==='superadmin'&&$a['account_status']==='active'&&($role!=='superadmin'||$status!=='active')&&$activeSup<=1)$error='You cannot deactivate or demote the last active Super Administrator.';else{$pdo->prepare("UPDATE accounts SET role=?,account_status=? WHERE id=?")->execute([$role,$status,$id]);log_audit($pdo,'UPDATE_ACCOUNT','account',$id,'Role/status changed');redirect('accounts.php');}}}
page_header('Edit Account');?><h1>Edit Account</h1><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><div class="panel"><div class="panel-body"><p><b><?=e($a['full_name'])?></b> · <?=e($a['username'])?></p><form method="post"><?=csrf_field()?><div class="field"><label>Role</label><select name="role"><?php foreach(['user'=>'User','admin'=>'Admin','superadmin'=>'Super Admin'] as $v=>$label):?><option value="<?=$v?>" <?=$a['role']===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="field"><label>Account Status</label><select name="account_status"><?php foreach(['active','inactive','suspended'] as $v):?><option <?=$a['account_status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><button>Save Changes</button></form></div></div><?php page_footer();?>
